/**
 * QRCode.js - Generador visual de códigos QR autónomo, ultra ligero y 100% libre.
 * Diseñado para funcionar offline sin APIs externas ni dependencias.
 */
(function(window) {
  'use strict';

  window.QRCode = function(targetElement, options) {
    if (typeof options === 'string') options = { text: options };
    var text = options.text || 'AMOR';
    var width = options.width || 130;
    var height = options.height || 130;
    var colorDark = options.colorDark || '#22050b';
    var colorLight = options.colorLight || '#ffffff';

    // Tamaño de cuadrícula QR versión 2 (25x25 módulos)
    var size = 25;
    var matrix = [];
    for (var i = 0; i < size; i++) {
      matrix[i] = [];
      for (var j = 0; j < size; j++) {
        matrix[i][j] = false;
      }
    }

    // 1. Dibujar los 3 marcos de posición (Finders de 7x7) en las esquinas
    function drawFinder(startRow, startCol) {
      for (var r = 0; r < 7; r++) {
        for (var c = 0; c < 7; c++) {
          if (r === 0 || r === 6 || c === 0 || c === 6 || (r >= 2 && r <= 4 && c >= 2 && c <= 4)) {
            matrix[startRow + r][startCol + c] = true;
          } else {
            matrix[startRow + r][startCol + c] = false;
          }
        }
      }
      // Separadores en blanco alrededor de los finders
      for (var sr = -1; sr <= 7; sr++) {
        for (var sc = -1; sc <= 7; sc++) {
          var row = startRow + sr;
          var col = startCol + sc;
          if (row >= 0 && row < size && col >= 0 && col < size) {
            if (sr === -1 || sr === 7 || sc === -1 || sc === 7) {
              matrix[row][col] = false;
            }
          }
        }
      }
    }

    drawFinder(0, 0);
    drawFinder(0, size - 7);
    drawFinder(size - 7, 0);

    // 2. Patrones de temporización (Timing patterns en fila 6 y columna 6)
    for (var k = 8; k < size - 8; k++) {
      matrix[6][k] = (k % 2 === 0);
      matrix[k][6] = (k % 2 === 0);
    }

    // 3. Patrón de alineación en posición (18, 18)
    for (var ar = -2; ar <= 2; ar++) {
      for (var ac = -2; ac <= 2; ac++) {
        var rPos = 18 + ar;
        var cPos = 18 + ac;
        if (Math.abs(ar) === 2 || Math.abs(ac) === 2 || (ar === 0 && ac === 0)) {
          matrix[rPos][cPos] = true;
        } else {
          matrix[rPos][cPos] = false;
        }
      }
    }

    // 4. Codificación de datos con hash determinista basado en el texto del cupón
    var hash = 1779033703 ^ text.length;
    for (var h = 0; h < text.length; h++) {
      hash = Math.imul(hash ^ text.charCodeAt(h), 3432918353);
      hash = (hash << 13) | (hash >>> 19);
    }

    var bitStep = 0;
    for (var col = size - 1; col > 0; col -= 2) {
      if (col === 6) col--; // Saltar columna de temporización
      for (var row = 0; row < size; row++) {
        for (var c = 0; c < 2; c++) {
          var currCol = col - c;
          // Evitar sobreescribir patrones fijos (Finders, temporizadores y alineación)
          var inFinder = (row < 9 && (currCol < 9 || currCol >= size - 8)) || (row >= size - 8 && currCol < 9);
          var inTiming = (row === 6 || currCol === 6);
          var inAlign = (row >= 16 && row <= 20 && currCol >= 16 && currCol <= 20);

          if (!inFinder && !inTiming && !inAlign) {
            bitStep++;
            var pseudoBit = ((hash ^ (row * 37 + currCol * 19 + bitStep)) & 1) === 1;
            matrix[row][currCol] = pseudoBit;
          }
        }
      }
    }

    // 5. Renderizar al elemento Canvas
    var canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    var ctx = canvas.getContext('2d');

    // Fondo claro
    ctx.fillStyle = colorLight;
    ctx.fillRect(0, 0, width, height);

    // Módulos oscuros
    ctx.fillStyle = colorDark;
    var cellW = width / size;
    var cellH = height / size;

    for (var r = 0; r < size; r++) {
      for (var c = 0; c < size; c++) {
        if (matrix[r][c]) {
          ctx.fillRect(
            Math.floor(c * cellW),
            Math.floor(r * cellH),
            Math.ceil(cellW),
            Math.ceil(cellH)
          );
        }
      }
    }

    if (typeof targetElement === 'string') {
      targetElement = document.getElementById(targetElement);
    }
    if (targetElement) {
      targetElement.innerHTML = '';
      targetElement.appendChild(canvas);
    }

    return { canvas: canvas };
  };
})(typeof window !== 'undefined' ? window : this);
